<?php
require_once '../../config/db.php';require_once '../../config/invoice_renderer.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../../index.php');$id=(int)($_GET['id']??0);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['record_payment'])){verify_csrf();try{$amount=round((float)$_POST['amount'],2);$accountId=(int)$_POST['account_id'];$pdo->beginTransaction();$s=$pdo->prepare('SELECT invoice_number,contact_id,grand_total,amount_paid,status,exchange_rate FROM invoices WHERE id=? FOR UPDATE');$s->execute([$id]);$locked=$s->fetch();if(!$locked||in_array($locked['status'],['paid','voided'],true))throw new RuntimeException('This invoice cannot receive payment.');$balance=round($locked['grand_total']-$locked['amount_paid'],2);if($amount<=0||$amount>$balance)throw new RuntimeException('Payment exceeds the outstanding balance.');$baseAmount=round($amount/(float)$locked['exchange_rate'],2);$s=$pdo->prepare('SELECT ledger_account_id FROM accounts WHERE id=? AND is_active=1 FOR UPDATE');$s->execute([$accountId]);$ledger=(int)$s->fetchColumn()?: (int)$pdo->query("SELECT id FROM chart_of_accounts WHERE account_code='1000'")->fetchColumn();$pdo->prepare("INSERT INTO payments(invoice_id,contact_id,account_id,payment_type,payment_date,amount,payment_method,reference_number,notes) VALUES(?,?,?,'inbound',?,?,?,?,?)")->execute([$id,$locked['contact_id'],$accountId,$_POST['payment_date'],$amount,trim((string)$_POST['payment_method']),trim((string)$_POST['reference_number']),trim((string)$_POST['notes'])]);$paymentId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE accounts SET current_balance=current_balance+? WHERE id=?')->execute([$baseAmount,$accountId]);$newPaid=round($locked['amount_paid']+$amount,2);$status=$newPaid>=$locked['grand_total']?'paid':'partial';$pdo->prepare('UPDATE invoices SET amount_paid=?,status=? WHERE id=?')->execute([$newPaid,$status,$id]);$ar=(int)$pdo->query("SELECT id FROM chart_of_accounts WHERE account_code='1200'")->fetchColumn();post_journal($pdo,$_POST['payment_date'],trim((string)$_POST['reference_number'])?:'PAY-'.$paymentId,'Payment for '.$locked['invoice_number'],[['account_id'=>$ledger,'debit'=>$baseAmount,'credit'=>0],['account_id'=>$ar,'contact_id'=>$locked['contact_id'],'debit'=>0,'credit'=>$baseAmount]],'payment',$paymentId);$pdo->commit();redirect('view_invoice.php?id='.$id.'&paid=1');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$s=$pdo->prepare('SELECT i.*,c.company_name,c.contact_person,c.email,c.billing_address,cur.symbol FROM invoices i JOIN contacts c ON c.id=i.contact_id JOIN currencies cur ON cur.code=i.currency_code WHERE i.id=?');$s->execute([$id]);$invoice=$s->fetch();if(!$invoice){http_response_code(404);exit('Invoice not found.');}$s=$pdo->prepare('SELECT * FROM invoice_lines WHERE invoice_id=? ORDER BY id');$s->execute([$id]);$lines=$s->fetchAll();$s=$pdo->prepare('SELECT * FROM invoice_templates WHERE id=?');$s->execute([$invoice['invoice_template_id']]);$template=$s->fetch()?:$pdo->query('SELECT * FROM invoice_templates ORDER BY is_default DESC,id LIMIT 1')->fetch();$s=$pdo->prepare('SELECT p.*,a.account_name FROM payments p JOIN accounts a ON a.id=p.account_id WHERE p.invoice_id=? ORDER BY payment_date DESC,id DESC');$s->execute([$id]);$payments=$s->fetchAll();$accounts=$pdo->query('SELECT id,account_name,current_balance FROM accounts WHERE is_active=1 ORDER BY account_name')->fetchAll();$balance=$invoice['grand_total']-$invoice['amount_paid'];require_once '../includes/header.php';require_once '../includes/sidebar.php';
?>
<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex justify-between items-center sticky top-0 z-10 print:hidden"><div class="flex gap-4 items-center"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><a href="invoices.php">←</a><div><h2 class="text-2xl font-bold"><?=h($invoice['invoice_number'])?></h2><p class="text-sm text-slate-500"><?=h($template['name']??'Invoice')?> template · <?=h($invoice['currency_code'])?></p></div></div><div class="flex gap-2"><button onclick="window.print()" class="border rounded-lg px-4 py-2">Print</button><a href="invoice_pdf.php?id=<?=$id?>" class="bg-slate-900 text-white rounded-lg px-4 py-2 font-semibold">Download PDF</a></div></header><div class="p-5 md:p-8 max-w-6xl mx-auto"><?php if(isset($_GET['created'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Invoice created using the selected template.</div><?php endif;?><?php if(isset($_GET['paid'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Payment recorded.</div><?php endif;?><?php if($error):?><div class="bg-rose-50 border p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?><div class="bg-white border rounded-2xl shadow-sm"><?=render_invoice_document($pdo,$invoice,$lines,$template)?></div>
<?php if($balance>0&&$invoice['status']!=='voided'):?><form method="post" class="bg-white border rounded-2xl p-6 mt-7 print:hidden"><?=csrf_field()?><h3 class="font-bold text-lg mb-4">Record payment</h3><p class="text-sm text-slate-500 mb-4">Payment is entered in <?=h($invoice['currency_code'])?>; the bank balance and ledger are converted to <?=h(setting($pdo,'base_currency','USD'))?>.</p><div class="grid md:grid-cols-3 gap-4"><label class="text-sm">Amount<input name="amount" type="number" step="0.01" min="0.01" max="<?=$balance?>" value="<?=number_format($balance,2,'.','')?>" required class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Deposit account<select name="account_id" class="block mt-1 w-full border rounded-lg px-3 py-2 bg-white"><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['account_name'])?> · <?=money($pdo,$a['current_balance'])?></option><?php endforeach;?></select></label><label class="text-sm">Payment date<input type="date" name="payment_date" value="<?=date('Y-m-d')?>" class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Method<input name="payment_method" value="Bank transfer" class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Reference<input name="reference_number" class="block mt-1 w-full border rounded-lg px-3 py-2"></label><label class="text-sm">Notes<input name="notes" class="block mt-1 w-full border rounded-lg px-3 py-2"></label></div><button name="record_payment" class="brand-bg text-white rounded-lg px-5 py-2.5 mt-4 font-semibold">Record payment</button></form><?php endif;?><?php if($payments):?><section class="bg-white border rounded-2xl p-6 mt-7 print:hidden"><h3 class="font-bold">Payment history</h3><?php foreach($payments as $p):?><div class="flex justify-between border-t py-3 mt-3"><div><strong><?=h(date('M j, Y',strtotime($p['payment_date'])))?></strong><p class="text-sm text-slate-500"><?=h($p['account_name'].' · '.$p['payment_method'].' · '.$p['reference_number'])?></p></div><strong><?=h($invoice['symbol']).number_format($p['amount'],2)?></strong></div><?php endforeach;?></section><?php endif;?></div></main><style>@media print{aside,header,.print\:hidden{display:none!important}main{height:auto!important;overflow:visible!important}}</style><?php require_once '../includes/footer.php';?>
